<?php

declare(strict_types=1);

namespace WPLokerBJM\Core\Container\Attributes;

use Attribute;

/**
 * Base class for all WordPress hook attributes.
 * @template TParams
 * Any Closure in attribute support param that can be resolved from Container, unless provider is `null` for InstanceRegistry side
 */
abstract class BaseHookAttribute
{
    /**
     * Attribute types autocomplete DX generated by generate-meta-hooks.php
     *
     * @param string|(\Closure(TParams...): string) $hook
     * @param int $priority
     * @param int $acceptedArgs
     * @param bool $deferRegister defer activation 
     * * deferRegister is forced true when $deferRegisterUntilHook is set
     * 
     * @param (\Closure(TParams...): bool)|null $executeIf decide whether to execute callback. 
     * * In addition resolving params from container, Closure can receive same params from hook execution callback by matching name.
     * * dependency resolving priority:
     * 1. params passed from hook by matching name (if any)
     * 2. params resolved from provider its container
     * 
     * 
     * 
     * @param (\Closure(TParams...): bool)|null $registerIf decide whether to register the hook, if deferRegister is true then registerIf evaluated after activation
     * 
     * @param (\Closure(TParams...): array)|array $tag can be used to activate defer/unregister registered hooks by tag
     * * Closure returned array must be flat array
     * 
     * 
     * 
     * @param string|(\Closure(TParams...): string)|null $deferRegisterUntilHook defer registration until the named 'action' trigger hook fires (implies defer); a Closure is resolved through the container and must return the trigger hook name
     * * it's scheduled under PHP_INT_MIN priority
     * 
     * 
     * 
     * @param bool $once consume-on-any-evaluation: the registration removes itself when dispatched invoker evaluation triggered, or proceeded to callback(executeIf null).
     * * The handler/invoker will become logically inert after $once used.
     * * The phsyical hook removal happen at temporary 'all' hook to avoid:
     * @link https://core.trac.wordpress.org/ticket/61263
     * @link https://core.trac.wordpress.org/ticket/64653
     */
    public function __construct(
        public readonly string|\Closure $hook,
        public readonly int $priority = 10,
        public readonly int $acceptedArgs = 1,
        public readonly ?\Closure $executeIf = null,
        public readonly ?\Closure $registerIf = null,
        public readonly array|\Closure $tag = [],
        public readonly string|\Closure|null $deferRegisterUntilHook = null,
        public bool $deferRegister = false,
        public readonly bool $once = false,
    ) {
        $this->deferRegister = $deferRegisterUntilHook !== null ? true : $deferRegister;
    }
}

/**
 * Attribute for WordPress actions.
 */
#[Attribute(Attribute::TARGET_METHOD | Attribute::TARGET_PROPERTY | Attribute::IS_REPEATABLE)]
class Action extends BaseHookAttribute {}
/**
 * Attribute for WordPress actions.
 */
#[Attribute(Attribute::TARGET_METHOD | Attribute::TARGET_PROPERTY | Attribute::IS_REPEATABLE)]
class Filter extends BaseHookAttribute {}
